     7→/// Load a spec from a TOML file
     8→pub fn load_spec(path: &Path) -> Result<Spec> {
     9→    let content = std::fs::read_to_string(path)
    10→        .with_context(|| format!("failed to read spec file: {}", path.display()))?;
    11→    parse_spec(&content)
    12→}
    13→
    14→/// Parse a spec from TOML string
    15→pub fn parse_spec(toml_str: &str) -> Result<Spec> {
    16→    toml::from_str(toml_str).context("failed to parse spec TOML")
    17→}
    18→
    19→/// Serialize a spec to TOML string (canonical form for hashing)
    20→pub fn serialize_spec(spec: &Spec) -> Result<String> {
    21→    toml::to_string(spec).context("failed to serialize spec")
    22→}
    23→
    24→/// Compute hash of a resolved spec (first 8 hex chars)
    25→pub fn hash_spec(spec: &Spec) -> Result<String> {
    26→    let toml_str = serialize_spec(spec)?;
    27→    let mut hasher = Sha256::new();
    28→    hasher.update(toml_str.as_bytes());
    29→    let result = hasher.finalize();
    30→    Ok(hex::encode(&result[..4]))
    31→}
    32→
    33→/// Save a spec to a TOML file, creating parent directories if needed
    34→pub fn save_spec(spec: &Spec, path: &Path) -> Result<()> {
    35→    if let Some(parent) = path.parent() {
    36→        std::fs::create_dir_all(parent)
    37→            .with_context(|| format!("failed to create directory: {}", parent.display()))?;
    38→    }
    39→    let content = serialize_spec(spec)?;
    40→    std::fs::write(path, &content)
    41→        .with_context(|| format!("failed to write spec file: {}", path.display()))
    42→}
    43→
    44→/// Save a spec snapshot with sequence number and hash: `{name}-{seq:03}-{hash}.toml`
    45→/// Returns the path of the created file.
    46→pub fn save_spec_snapshot(spec: &Spec, name: &str, dir: &Path) -> Result<PathBuf> {
    47→    std::fs::create_dir_all(dir)
    48→        .with_context(|| format!("failed to create directory: {}", dir.display()))?;
    49→
    50→    // Find highest existing sequence number for this name
    51→    let prefix = format!("{}-", name);
    52→    let next_seq = std::fs::read_dir(dir)
    53→        .with_context(|| format!("failed to read directory: {}", dir.display()))?
    54→        .filter_map(|entry| entry.ok())
    55→        .filter_map(|entry| {
    56→            let filename = entry.file_name().to_string_lossy().into_owned();
    57→            if filename.starts_with(&prefix) && filename.ends_with(".toml") {
    58→                // Extract sequence number: {name}-{seq:03}-{hash}.toml
    59→                let rest = filename.strip_prefix(&prefix)?;
    60→                let seq_str = rest.split('-').next()?;
    61→                seq_str.parse::<u32>().ok()
    62→            } else {
    63→                None
    64→            }
    65→        })
    66→        .max()
    67→        .map(|n| n + 1)
    68→        .unwrap_or(1);
    69→
    70→    let hash = hash_spec(spec)?;
    71→    let filename = format!("{}-{:03}-{}.toml", name, next_seq, hash);
    72→    let path = dir.join(&filename);
    73→
    74→    let content = serialize_spec(spec)?;
    75→    std::fs::write(&path, &content)
    76→        .with_context(|| format!("failed to write spec file: {}", path.display()))?;
    77→
    78→    Ok(path)
    79→}
