    36→/// Find the workspace root by looking for Cargo.toml with [workspace]
    37→pub fn find_workspace_root() -> Result<PathBuf> {
    38→    let mut dir = std::env::current_dir()?;
    39→    loop {
    40→        let cargo_toml = dir.join("Cargo.toml");
    41→        if cargo_toml.exists() {
    42→            let content = std::fs::read_to_string(&cargo_toml)?;
    43→            if content.contains("[workspace]") {
    44→                return Ok(dir);
    45→            }
    46→        }
    47→        if !dir.pop() {
    48→            bail!("could not find workspace root");
    49→        }
    50→    }
    51→}
