    71→/// Find the tspec for a crate - tries as path first, then relative to crate_dir
    72→/// Returns None if no tspec exists (plain cargo build will be used)
    73→pub fn find_tspec(crate_dir: &Path, explicit: Option<&str>) -> Result<Option<PathBuf>> {
    74→    match explicit {
    75→        Some(name) => {
    76→            // Try as path first (relative to cwd or absolute)
    77→            let as_path = PathBuf::from(name);
    78→            if as_path.exists() {
    79→                return Ok(Some(as_path.canonicalize().unwrap_or(as_path)));
    80→            }
    81→
    82→            // Fallback: relative to crate directory
    83→            let in_crate = crate_dir.join(name);
    84→            if in_crate.exists() {
    85→                return Ok(Some(in_crate));
    86→            }
    87→
    88→            bail!("tspec not found: {}", name);
    89→        }
    90→        None => {
    91→            let default = crate_dir.join("tspec.toml");
    92→            if default.exists() {
    93→                Ok(Some(default))
    94→            } else {
    95→                Ok(None) // No tspec = plain cargo build
    96→            }
    97→        }
    98→    }
    99→}
