   101→/// Get binary path for a build with a spec
   102→pub fn get_binary_path(workspace: &Path, crate_name: &str, spec: &Spec, release: bool) -> PathBuf {
   103→    let is_release = release
   104→        || spec
   105→            .cargo
   106→            .iter()
   107→            .any(|p| matches!(p, CargoParam::Profile(Profile::Release)));
   108→
   109→    let target = spec.cargo.iter().find_map(|p| match p {
   110→        CargoParam::TargetTriple(t) => Some(t.clone()),
   111→        CargoParam::TargetJson(p) => p.file_stem().map(|s| s.to_string_lossy().to_string()),
   112→        _ => None,
   113→    });
   114→
   115→    let profile_dir = if is_release { "release" } else { "debug" };
   116→
   117→    match target {
   118→        Some(t) => workspace
   119→            .join("target")
   120→            .join(t)
   121→            .join(profile_dir)
   122→            .join(crate_name),
   123→        None => workspace.join("target").join(profile_dir).join(crate_name),
   124→    }
   125→}
   126→
   127→/// Get binary path for a simple build (no spec)
   128→pub fn get_binary_path_simple(workspace: &Path, crate_name: &str, release: bool) -> PathBuf {
   129→    let profile_dir = if release { "release" } else { "debug" };
   130→    workspace.join("target").join(profile_dir).join(crate_name)
   131→}
