    13→/// Compare two specs for a crate
    14→pub fn compare_specs(crate_name: &str, spec_a: &str, spec_b: &str, release: bool) -> Result<()> {
    15→    println!("Comparing {} builds:\n", crate_name);
    16→
    17→    // Build, strip, and run spec A
