    19→
    20→    println!();
    21→
    22→    // Build, strip, and run spec B
    23→    let result_b = build_and_run(crate_name, spec_b, release)?;
    24→
    25→    // Print comparison
    26→    println!();
    27→    print_comparison(&result_a, &result_b, spec_a, spec_b);
    28→
    29→    Ok(())
    30→}
