    32→fn build_and_run(crate_name: &str, spec: &str, release: bool) -> Result<SpecResult> {
    33→    println!("  {}:", spec);
    34→
    35→    // Build
    36→    let build_result = build_crate(crate_name, Some(spec), release)?;
    37→
    38→    // Strip
