    40→
    41→    // Get size
    42→    let size = binary_size(&build_result.binary_path)?;
    43→    println!("    size: {} bytes", format_size(size));
    44→
    45→    // Run
    46→    let exit_code = run_binary(&build_result.binary_path)?;
    47→    println!("    exit: {}", exit_code);
