    52→fn print_comparison(a: &SpecResult, b: &SpecResult, spec_a: &str, spec_b: &str) {
    53→    // Size comparison
    54→    let size_diff = (a.size as i64 - b.size as i64).unsigned_abs();
    55→    let larger_size = a.size.max(b.size);
    56→    let size_pct = if larger_size > 0 {
    57→        (size_diff as f64 / larger_size as f64) * 100.0
    58→    } else {
    59→        0.0
    60→    };
    61→
    62→    let size_str = if a.size < b.size {
    63→        format!(
    64→            "{} is {} smaller ({:.1}%)",
    65→            spec_a,
    66→            format_size(size_diff),
    67→            size_pct
    68→        )
    69→    } else if b.size < a.size {
    70→        format!(
    71→            "{} is {} smaller ({:.1}%)",
    72→            spec_b,
    73→            format_size(size_diff),
    74→            size_pct
    75→        )
    76→    } else {
